r {\n  width: 36px;\n}\n\n.chat-panel__title-wrap {\n  min-width: 0;\n  text-align: center;\n}\n\n.chat-panel__name {\n  min-width: 0;\n  font-size: 16px;\n  font-weight: 700;\n  letter-spacing: 0.4px;\n  color: #f8fafc;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  min-height: 1.35em;\n}\n\n.chat-panel__name--idle {\n  background: linear-gradient(90deg, #f8fafc 0%, var(--gal-pink) 40%, var(--gal-blue) 60%, #f8fafc 100%);\n  background-size: 220% auto;\n  -webkit-background-clip: text;\n  background-clip: text;\n  color: transparent;\n  animation: chat-name-shimmer 4s linear infinite;\n}\n\n.chat-panel__subtitle {\n  display: block;\n  margin-top: 2px;\n  font-size: 9px;\n  letter-spacing: 0.22em;\n  color: rgba(226, 232, 240, 0.45);\n}\n\n@keyframes chat-name-shimmer {\n  0% {\n    background-position: 220% center;\n  }\n\n  100% {\n    background-position: -220% center;\n  }\n}\n\n.chat-panel__messages {\n  position: relative;\n  z-index: 1;\n  flex: 1;\n  min-height: 0;\n  overflow-y: auto;\n  padding: 16px 14px;\n  display: flex;\n  flex-direction: column;\n  gap: 14px;\n\n  &::-webkit-scrollbar {\n    width: 5px;\n  }\n\n  &::-webkit-scrollbar-thumb {\n    border-radius: 999px;\n    background: linear-gradient(var(--gal-pink), var(--gal-blue));\n  }\n}\n\n.chat-panel__empty {\n  margin: auto;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: 10px;\n  color: rgba(226, 232, 240, 0.45);\n  font-size: 12px;\n\n  i {\n    font-size: 28px;\n    background: linear-gradient(135deg, var(--gal-pink), var(--gal-blue));\n    -webkit-background-clip: text;\n    background-clip: text;\n    color: transparent;\n  }\n}\n\n.chat-message {\n  display: flex;\n  align-items: flex-end;\n  gap: 10px;\n  max-width: 100%;\n\n  &--user {\n    flex-direction: row;\n    justify-content: flex-end;\n\n    .chat-message__bubble {\n      background: linear-gradient(135deg, var(--gal-pink-deep) 0%, var(--gal-pink) 55%, #fb7185 100%);\n      color: #fff;\n      border: 1px solid rgba(255, 255, 255, 0.2);\n      border-bottom-right-radius: 6px;\n      box-shadow: 0 8px 24px rgba(236, 72, 153, 0.28);\n    }\n  }\n\n  &--npc {\n    flex-direction: row;\n    justify-content: flex-start;\n\n    .chat-message__bubble {\n      background: linear-gradient(145deg, rgba(96, 165, 250, 0.22) 0%, rgba(167, 139, 250, 0.16) 100%);\n      border: 1px solid rgba(147, 197, 253, 0.28);\n      border-bottom-left-radius: 6px;\n      box-shadow: 0 8px 22px rgba(59, 130, 246, 0.12);\n      backdrop-filter: blur(8px);\n    }\n  }\n\n  &--system {\n    justify-content: center;\n\n    .chat-message__bubble {\n      background: rgba(255, 255, 255, 0.04);\n      color: rgba(226, 232, 240, 0.55);\n      font-size: 10px;\n      padding: 5px 12px;\n      border: 1px dashed rgba(255, 255, 255, 0.12);\n      border-radius: 999px;\n      max-width: 100%;\n    }\n  }\n\n  &--typing .chat-message__bubble {\n    min-width: 88px;\n  }\n}\n\n.chat-message__avatar {\n  align-self: flex-end;\n\n  &--user :deep(.chat-avatar) {\n    border-color: rgba(244, 114, 182, 0.55);\n    box-shadow: 0 0 0 2px rgba(244, 114, 182, 0.15);\n  }\n\n  &--npc :deep(.chat-avatar) {\n    border-color: rgba(96, 165, 250, 0.55);\n    box-shadow: 0 0 0 2px rgba(96, 165, 250, 0.15);\n  }\n}\n\n.chat-message__bubble {\n  max-width: calc(100% - 50px);\n  padding: 10px 14px;\n  border-radius: 16px;\n  font-size: 13px;\n  line-height: 1.5;\n  word-break: break-word;\n  color: #f1f5f9;\n}\n\n.chat-message__bubble--typing {\n  display: flex;\n  align-items: center;\n  gap: 5px;\n  padding: 12px 14px;\n}\n\n.typing-dot {\n  width: 7px;\n  height: 7px;\n  border-radius: 50%;\n  background: linear-gradient(180deg, var(--gal-blue) 0%, var(--gal-violet) 100%);\n}\n\n.typing-label {\n  margin-left: 6px;\n  font-size: 11px;\n  color: rgba(226, 232, 240, 0.55);\n  white-space: nowrap;\n}\n\n.chat-panel__composer {\n  position: relative;\n  z-index: 1;\n  flex-shrink: 0;\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  padding: 12px 14px 14px;\n  border-top: 1px solid var(--gal-border);\n  background: linear-gradient(0deg, rgba(12, 18, 34, 0.95) 0%, rgba(255, 255, 255, 0.04) 100%);\n  backdrop-filter: blur(14px);\n}\n\n.chat-panel__input-wrap {\n  flex: 1;\n  min-width: 0;\n  padding: 1px;\n  border-radius: 999px;\n  background: var(--gal-gradient-input);\n}\n\n.chat-panel__input {\n  width: 100%;\n  padding: 10px 16px;\n  border-radius: 999px;\n  border: none;\n  background: rgba(15, 20, 38, 0.92);\n  color: #f8fafc;\n  font-size: 13px;\n  font-family: inherit;\n\n  &::placeholder {\n    color: rgba(226, 232, 240, 0.38);\n  }\n\n  &:focus {\n    outline: none;\n  }\n\n  &:disabled {\n    opacity: 0.65;\n    cursor: wait;\n  }\n}\n\n.chat-panel__send {\n  flex-shrink: 0;\n  width: 44px;\n  height: 44px;\n  border: none;\n  border-radius: 14px;\n  background: var(--gal-gradient-primary);\n  color: #fff;\n  font-size: 15px;\n  cursor: pointer;\n  box-shadow: 0 8px 22px rgba(99, 102, 241, 0.35);\n  transition:\n    transform 0.15s,\n    box-shadow 0.2s,\n    opacity 0.2s;\n\n  &:hover:not(:disabled) {\n    transform: translateY(-1px);\n    box-shadow: 0 10px 28px rgba(236, 72, 153, 0.35);\n  }\n\n  &:disabled {\n    opacity: 0.55;\n    cursor: not-allowed;\n    box-shadow: none;\n  }\n}\n"],"sourceRoot":""}]);
