import { mountStreamingMessages } from '@util/streaming';
import GameRoot from '../../手机角色状态栏/GameRoot.vue';
import '../../手机角色状态栏/global.scss';
import { isOpeningFloor } from '../../手机角色状态栏/messageScope';
$(async () => {
    await Promise.race([
        waitGlobalInitialized('Mvu'),
        new Promise(resolve => setTimeout(resolve, 5000)),
    ]);
    const { unmount } = mountStreamingMessages(() => createApp(GameRoot).use(createPinia()), {
        host: 'iframe',
        prefix: 'gal-game-ui',
        filter: message_id => isOpeningFloor(message_id),
    });
    console.info('[异世界大冒险] 已在第一条消息挂载游戏界面（开局 → GAL）');
    $(window).on('pagehide', () => unmount());
});
