}\n\n.top-bar__icon-wrap {\n  width: 32px;\n  height: 32px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  border-radius: 10px;\n  background: var(--gal-gradient-primary);\n  box-shadow: 0 4px 14px rgba(236, 72, 153, 0.35);\n\n  i {\n    font-size: 14px;\n    color: #fff;\n  }\n}\n\n.top-bar__title-text {\n  background: linear-gradient(90deg, #fff 0%, var(--gal-pink) 50%, var(--gal-blue) 100%);\n  -webkit-background-clip: text;\n  background-clip: text;\n  color: transparent;\n}\n\n.top-bar__actions {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  flex-shrink: 0;\n}\n\n.top-bar__bgm {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  min-width: 0;\n  padding: 4px 10px 4px 4px;\n  border-radius: var(--gal-radius-pill);\n  background: var(--gal-glass);\n  border: 1px solid var(--gal-border);\n}\n\n.top-bar__btn {\n  width: 32px;\n  height: 32px;\n  border: 1px solid var(--gal-border);\n  border-radius: 10px;\n  background: var(--gal-glass);\n  color: var(--gal-text);\n  cursor: pointer;\n  flex-shrink: 0;\n  transition: all var(--gal-transition);\n\n  &:hover {\n    border-color: rgba(244, 114, 182, 0.45);\n    background: var(--gal-pink-soft);\n  }\n}\n\n.top-bar__btn--fullscreen {\n  width: auto;\n  min-width: 32px;\n  padding: 0 12px;\n  gap: 6px;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n}\n\n.top-bar__btn-text {\n  font-size: 11px;\n  font-weight: 600;\n}\n\n.top-bar__btn--active,\n.top-bar__btn--fullscreen:hover {\n  border-color: rgba(96, 165, 250, 0.5);\n  color: var(--gal-blue);\n  background: var(--gal-blue-soft);\n}\n\n.top-bar__bgm-label {\n  font-size: 10px;\n  color: var(--gal-text-muted);\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  max-width: 100px;\n}\n"],"sourceRoot":""}]);
