import dedent from 'dedent';
import { getLatestGalMessage, normalizeGenerateResult } from './gameFlow';
import { parseGalFromMessage } from './galParser';
const CHAT_VAR_KEY = 'gal_private_chats';
const PrivateChatEntrySchema = z.object({
    id: z.string(),
    role: z.enum(['user', 'npc', 'system']),
    text: z.string(),
});
const PrivateChatStoreSchema = z.record(z.string(), z.array(PrivateChatEntrySchema)).prefault({});
function load_store() {
    const raw = _.get(getVariables({ type: 'chat' }), CHAT_VAR_KEY, {});
    return PrivateChatStoreSchema.parse(raw);
}
function save_store(store) {
    const chat_vars = klona(getVariables({ type: 'chat' }));
    _.set(chat_vars, CHAT_VAR_KEY, store);
    replaceVariables(chat_vars, { type: 'chat' });
}
export function load_npc_thread(npc_name) {
    const store = load_store();
    return store[npc_name] ?? [];
}
function persist_thread(npc_name, thread) {
    const store = load_store();
    store[npc_name] = thread;
    save_store(store);
}
export function append_thread_message(npc_name, role, text) {
    const thread = load_npc_thread(npc_name);
    const next = [...thread, { id: `${Date.now()}-${thread.length}`, role, text }];
    persist_thread(npc_name, next);
    return next;
}
function ensure_opening_system(npc_name) {
    const thread = load_npc_thread(npc_name);
    if (thread.length)
        return thread;
    return append_thread_message(npc_name, 'system', `已与 ${npc_name} 开始私聊`);
}
export function open_npc_thread(npc_name) {
    return ensure_opening_system(npc_name);
}
function summarize_gal_context() {
    const latest = getLatestGalMessage();
    if (!latest)
        return '（暂无主线剧情）';
    const parsed = parseGalFromMessage(latest.message);
    if (!parsed?.dialogues.length) {
        return latest.message.replace(/<[^>]+>/g, ' ').slice(0, 400);
    }
    const recent = parsed.dialogues.slice(-4);
    return recent
        .map(d => {
        if (d.dialogue_kind === 'narrator')
            return `[旁白] ${d.text ?? ''}`;
        return `[${d.speaker ?? '角色'}] ${d.text ?? ''}`;
    })
        .join('\n');
}
function build_system_prompt(npc_name, npc, player_name) {
    return dedent `
    你正在扮演私聊对象「${npc_name}」，与玩家「${player_name}」进行一对一线上私聊。
    这是独立于 GAL 主界面的私聊通道，请只输出 ${npc_name} 的口语化回复正文。

    【${npc_name}当前状态】
    - 身份：${npc.身份 || '未知'}
    - 性别：${npc.性别}
    - 位置：${npc.位置}
    - 外貌穿着：${npc.外貌穿着 || '—'}
    - 内心想法：${npc.内心想法 || '—'}
    - 好感度：${npc.好感度}

    【当前主线剧情摘要（供参考）】
    ${summarize_gal_context()}

    【输出要求】
    - 只输出 ${npc_name} 要说的话，不要输出 gal、UpdateVariable、选项、旁白标签
    - 语气符合人设，与主线剧情连贯
    - 回复 1~3 句即可，可分行；不要加「${npc_name}:」等前缀
  `;
}
function format_thread_for_prompt(thread, player_name, npc_name) {
    const dialogues = thread.filter(m => m.role === 'user' || m.role === 'npc').slice(-16);
    if (!dialogues.length)
        return '（尚无聊天记录）';
    return dialogues
        .map(m => {
        const speaker = m.role === 'user' ? player_name : npc_name;
        return `${speaker}：${m.text}`;
    })
        .join('\n');
}
function parse_npc_replies(raw, npc_name) {
    let text = normalizeGenerateResult(raw)
        .replace(/<UpdateVariable>[\s\S]*$/i, '')
        .replace(/<gal>[\s\S]*?<\/gal>/gi, '')
        .replace(/^[\s\S]*?<\/gal>/i, '')
        .trim();
    text = text.replace(new RegExp(`^${_.escapeRegExp(npc_name)}\\s*[：:]`, 'gm'), '').trim();
    const lines = text
        .split(/\n+/)
        .map(line => line.trim())
        .filter(line => line && !/^[<[]/.test(line));
    if (lines.length)
        return lines.slice(0, 4);
    return [text.slice(0, 500) || '…'];
}
/**
 * 独立私聊：不写入主聊天楼层，用 generateRaw 单独请求，避免与 GAL 共用 generate 导致 400
 */
export async function send_private_chat(npc_name, user_text, player_name, npc, on_thread_update) {
    const input = user_text.trim();
    if (!input)
        return load_npc_thread(npc_name);
    ensure_opening_system(npc_name);
    let thread = append_thread_message(npc_name, 'user', input);
    on_thread_update?.(thread);
    const history = format_thread_for_prompt(thread, player_name, npc_name);
    const system = build_system_prompt(npc_name, npc, player_name);
    const user_prompt = dedent `
    【私聊记录】
    ${history}

    【玩家刚发送】
    ${input}

    请以 ${npc_name} 的身份回复。
  `;
    const raw = await generateRaw({
        ordered_prompts: [
            'char_description',
            'char_personality',
            'persona_description',
            { role: 'system', content: system },
            { role: 'user', content: user_prompt },
        ],
        max_chat_history: 0,
        should_silence: true,
        overrides: {
            world_info_before: '',
            world_info_after: '',
            dialogue_examples: '',
            scenario: '',
            chat_history: { prompts: [], with_depth_entries: false },
        },
    });
    const replies = parse_npc_replies(raw, npc_name);
    for (const line of replies) {
        thread = append_thread_message(npc_name, 'npc', line);
        on_thread_update?.(thread);
    }
    return thread;
}
