import { resolveMediaUrl as resolveUrl } from './media';

export type GalDialogueKind = 'character' | 'narrator' | 'other';

export interface GalTimelineEntry {
  kind: 'bgm' | 'background' | 'dialogue' | 'choice';
  bgm?: string;
  background?: string;
  dialogue_kind?: GalDialogueKind;
  speaker?: string;
  pic?: string;
  text?: string;
  choice_text?: string;
}

export interface ParsedGal {
  timeline: GalTimelineEntry[];
  dialogues: GalTimelineEntry[];
  choices: string[];
}

const GAL_BLOCK_RE = /<gal>([\s\S]*?)<\/gal>/i;

function parse_character_dialogue(body: string): GalTimelineEntry {
  const pic_match = body.match(/^([\s\S]*?)<pic>([\s\S]*?)<\/pic>([\s\S]*)$/i);
  if (pic_match) {
    return {
      kind: 'dialogue',
      dialogue_kind: 'character',
      speaker: pic_match[1].trim(),
      pic: resolveUrl(pic_match[2].trim()),
      text: pic_match[3].trim(),
    };
  }

  return {
    kind: 'dialogue',
    dialogue_kind: 'character',
    speaker: body.split(/[\n\r]/)[0]?.trim() || '角色',
    text: body,
  };
}

function parseOrderedTags(inner: string): GalTimelineEntry[] {
  const entries: GalTimelineEntry[] = [];
  const tag_re =
    /<(bgm|background|j|s|p|other|choice|opt)(?:\s+name="([^"]*)")?\s*>([\s\S]*?)<\/\1>/gi;

  let match: RegExpExecArray | null;
  while ((match = tag_re.exec(inner)) !== null) {
    const tag = match[1].toLowerCase();
    const attr = match[2]?.trim();
    const body = match[3].trim();

    if (tag === 'bgm') {
      entries.push({ kind: 'bgm', bgm: resolveUrl(body) });
      continue;
    }
    if (tag === 'background') {
      entries.push({ kind: 'background', background: resolveUrl(body) });
      continue;
    }
    if (tag === 'choice' || tag === 'opt') {
      entries.push({ kind: 'choice', choice_text: body });
      continue;
    }
    if (tag === 'p') {
      entries.push({
        kind: 'dialogue',
        dialogue_kind: 'narrator',
        speaker: '旁白',
        text: body,
      });
      continue;
    }
    if (tag === 'other') {
      entries.push({
        kind: 'dialogue',
        dialogue_kind: 'other',
        speaker: attr || '未知',
        text: body,
      });
      continue;
    }
    if (tag === 'j' || tag === 's') {
      entries.push(parse_character_dialogue(body));
    }
  }

  return entries;
}

export function parseGalFromMessage(message: string): ParsedGal | null {
  const block = message.match(GAL_BLOCK_RE)?.[1];
  if (!block) return null;

  const timeline = parseOrderedTags(block);
  const dialogues = timeline.filter(entry => entry.kind === 'dialogue');
  const choices = timeline.filter(entry => entry.kind === 'choice').map(entry => entry.choice_text ?? '');

  return { timeline, dialogues, choices: choices.slice(0, 4) };
}

export function resolveMediaState(timeline: GalTimelineEntry[], dialogue_index: number): {
  bgm: string;
  background: string;
} {
  let bgm = '';
  let background = '';
  let dialogue_seen = -1;

  for (const entry of timeline) {
    if (entry.kind === 'bgm' && entry.bgm) bgm = entry.bgm;
    if (entry.kind === 'background' && entry.background) background = entry.background;
    if (entry.kind === 'dialogue') {
      dialogue_seen += 1;
      if (dialogue_seen >= dialogue_index) break;
    }
  }

  return { bgm, background };
}

export { isVideoUrl, resolveMediaUrl } from './media';
